local ScaffoldMaker = {}
local PRODUCTS = {
    simple_wood_scaffold = { name = "Preprosto leseno gradbeno stojalo", woodCost = 4, ropeCost = 2, time = 4, cost = 120, science = 15, happiness = 1, description = "Preprosto leseno gradbeno stojalo za gradnjo." },
    iron_reinforced_scaffold = { name = "Železnookrepljeno stojalo", woodCost = 3, ironCost = 2, ropeCost = 2, time = 7, cost = 320, science = 28, happiness = 2, prestige = 2, description = "Železnookrepljeno stojalo za trgovce." },
    silver_banded_scaffold = { name = "Srebrnopasno stojalo", woodCost = 3, ironCost = 2, silverCost = 1, ropeCost = 2, time = 10, cost = 760, science = 42, happiness = 2, prestige = 6, description = "Srebrnopasno stojalo za plemiče." },
    gold_trimmed_scaffold = { name = "Zlatookrasno stojalo", woodCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, ropeCost = 2, time = 14, cost = 1700, science = 56, happiness = 3, prestige = 14, description = "Zlatookrasno stojalo za visoke plemiče." },
    jewel_set_scaffold = { name = "Draguljasto stojalo", woodCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, ropeCost = 2, jewelCost = 1, time = 18, cost = 3600, science = 72, happiness = 5, prestige = 27, description = "Stojalo z draguljem za visoko plemstvo." },
    royal_grand_scaffold = { name = "Kraljevski veliki stojalo", woodCost = 5, ironCost = 3, goldCost = 2, silverCost = 2, ropeCost = 2, jewelCost = 2, pearlCost = 2, time = 25, cost = 7500, science = 90, happiness = 12, prestige = 58, description = "Veliki kraljevski stojalo z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    scaffold_workshop = { name = "Stojalna delavnica", cost = { gold = 280, wood = 160, stone = 120, rope = 6 }, upkeep = 6, qualityBonus = 5 },
    construction_loft = { name = "Gradbena podstrešje", cost = { gold = 1000, wood = 320, stone = 280, iron = 6, silver = 6 }, upkeep = 23, qualityBonus = 18 },
    master_builder_atelier = { name = "Mojstrski gradbeni atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_construction_palace = { name = "Kraljevska gradbena palača", cost = { gold = 11500, wood = 600, stone = 800, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
ScaffoldMaker.woodStock = 20; ScaffoldMaker.ropeStock = 12; ScaffoldMaker.ironStock = 10; ScaffoldMaker.silverStock = 6; ScaffoldMaker.goldStock = 6; ScaffoldMaker.jewelStock = 4; ScaffoldMaker.pearlStock = 4
ScaffoldMaker.productStock = {}; ScaffoldMaker.buildings = {}; ScaffoldMaker.maker = nil; ScaffoldMaker.activeMaking = {}; ScaffoldMaker.totalProducts = 0; ScaffoldMaker.dayTimer = 0
function ScaffoldMaker.init() ScaffoldMaker.woodStock=20; ScaffoldMaker.ropeStock=12; ScaffoldMaker.ironStock=10; ScaffoldMaker.silverStock=6; ScaffoldMaker.goldStock=6; ScaffoldMaker.jewelStock=4; ScaffoldMaker.pearlStock=4; ScaffoldMaker.productStock={}; ScaffoldMaker.buildings={}; ScaffoldMaker.maker=nil; ScaffoldMaker.activeMaking={}; ScaffoldMaker.totalProducts=0; ScaffoldMaker.dayTimer=0; print("[ScaffoldMaker] Royal Scaffold Maker System initialized (6 products, 4 buildings)") end
function ScaffoldMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ScaffoldMaker.maker={name=n or ("Stojalar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stojalar najet: %s (spretnost: %d)",ScaffoldMaker.maker.name,s),"success") end; return true end
function ScaffoldMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ScaffoldMaker.build(id) local ok,e=ScaffoldMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ScaffoldMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ScaffoldMaker.getQualityBonus() local b=0; for _,bd in ipairs(ScaffoldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ScaffoldMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ScaffoldMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ropeCost and ScaffoldMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.ironCost and ScaffoldMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and ScaffoldMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ScaffoldMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ScaffoldMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ScaffoldMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ScaffoldMaker.buildings==0 then return false,"Potrebna stojalna delavnica" end; if not ScaffoldMaker.maker then return false,"Potreben stojalar" end; return true end
function ScaffoldMaker.make(pt,qty) qty=qty or 1; local ok,e=ScaffoldMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ScaffoldMaker.woodStock=ScaffoldMaker.woodStock-d.woodCost*qty end; if d.ropeCost then ScaffoldMaker.ropeStock=ScaffoldMaker.ropeStock-d.ropeCost*qty end; if d.ironCost then ScaffoldMaker.ironStock=ScaffoldMaker.ironStock-d.ironCost*qty end; if d.silverCost then ScaffoldMaker.silverStock=ScaffoldMaker.silverStock-d.silverCost*qty end; if d.goldCost then ScaffoldMaker.goldStock=ScaffoldMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ScaffoldMaker.jewelStock=ScaffoldMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ScaffoldMaker.pearlStock=ScaffoldMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ScaffoldMaker.maker then t=math.max(1,t-math.floor(ScaffoldMaker.maker.skill/13)) end; table.insert(ScaffoldMaker.activeMaking,{id="scaffold_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ScaffoldMaker.completeMaking(m) local q=1.0+(ScaffoldMaker.getQualityBonus()/100); if ScaffoldMaker.maker then q=q+(ScaffoldMaker.maker.skill/140) end; q=math.min(2.5,q); ScaffoldMaker.productStock[m.productType]=(ScaffoldMaker.productStock[m.productType] or 0)+m.quantity; ScaffoldMaker.totalProducts=ScaffoldMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ScaffoldMaker.maker then ScaffoldMaker.maker.itemsMade=ScaffoldMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ScaffoldMaker.maker.skill=math.min(100,ScaffoldMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stojalo izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"scaffold.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function ScaffoldMaker.update(dt) if not _G.state then return end; ScaffoldMaker.dayTimer=ScaffoldMaker.dayTimer+dt; if ScaffoldMaker.dayTimer>=30 then ScaffoldMaker.dayTimer=0; for i=#ScaffoldMaker.activeMaking,1,-1 do local m=ScaffoldMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ScaffoldMaker.completeMaking(m); table.remove(ScaffoldMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ScaffoldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ScaffoldMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ScaffoldMaker.getStats() return {woodStock=ScaffoldMaker.woodStock,ropeStock=ScaffoldMaker.ropeStock,ironStock=ScaffoldMaker.ironStock,silverStock=ScaffoldMaker.silverStock,goldStock=ScaffoldMaker.goldStock,jewelStock=ScaffoldMaker.jewelStock,pearlStock=ScaffoldMaker.pearlStock,productStock=ScaffoldMaker.productStock,numBuildings=#ScaffoldMaker.buildings,hasMaker=ScaffoldMaker.maker~=nil,makerName=ScaffoldMaker.maker and ScaffoldMaker.maker.name or "—",makerSkill=ScaffoldMaker.maker and ScaffoldMaker.maker.skill or 0,activeMaking=#ScaffoldMaker.activeMaking,totalProducts=ScaffoldMaker.totalProducts} end
return ScaffoldMaker
